{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Across all four categories, scale observed context vectors by 0.75 + 0.5 times the percentile rank of log1p training frequency. This bounded cue may improve context reliability while preserving learned embeddings, topology, readout, loss and optimizer. Padding stays zero and the exclusive mask retains scale 1. The checkpointed buffer is restored by the existing predictor writer, which imports the updated model class.",
      "edits": [
        {
          "find": "        self.mask_token = itemnum + 1\n        self.item_emb = nn.Embedding(itemnum + 2, hidden_units, padding_idx=0)",
          "replace": "        self.mask_token = itemnum + 1\n        self.register_buffer(\"input_scale\", torch.ones(itemnum + 2))\n        self.input_scale[0] = 0.0\n        self.item_emb = nn.Embedding(itemnum + 2, hidden_units, padding_idx=0)"
        },
        {
          "find": "        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)",
          "replace": "        x = item_vectors * self.input_scale[seq].unsqueeze(-1) * (self.hidden_units ** 0.5) + self.pos_emb(pos)"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    item_counts = np.zeros(itemnum + 2, dtype=np.int64)\n    for history in user_train.values():\n        np.add.at(item_counts, np.asarray(history, dtype=np.int64), 1)\n    log_frequency = np.log1p(item_counts[1:itemnum + 1].astype(np.float64))\n    _, inverse, tie_counts = np.unique(\n        log_frequency, return_inverse=True, return_counts=True\n    )\n    first_rank = np.cumsum(tie_counts) - tie_counts\n    midpoint_rank = first_rank + (tie_counts - 1) / 2.0\n    if itemnum > 1:\n        percentile = midpoint_rank[inverse] / float(itemnum - 1)\n    else:\n        percentile = np.full(itemnum, 0.5, dtype=np.float64)\n    input_scale = np.ones(itemnum + 2, dtype=np.float32)\n    input_scale[0] = 0.0\n    input_scale[1:itemnum + 1] = (0.75 + 0.5 * percentile).astype(np.float32)\n    with torch.no_grad():\n        model.input_scale.copy_(torch.as_tensor(input_scale, device=device))\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Add training-only frequency percentile input scaling to each category's single BERT4Rec model, persisted in its checkpoint and automatically restored during prediction."
}
